  public List<Actor> Targets(){var result=liveTargets;result.Clear();foreach(var e in enemies)if(e.hp>0)result.Add(e);if(boss!=null&&boss.active&&boss.hp>0)result.Add(boss);return result;}
  bool SwordAway(){foreach(var p in projectiles)if(!p.hostile&&!p.qi&&!p.rain)return true;return false;}
  void Melee(){float age=clock-attackAt;if(age<.1f||age>=.235f)return;if(soundedAttack!=attackAt){soundedAttack=attackAt;audio.Play("slash");}
   if(run!=null&&run.Level("echo")>0&&run.melees%3==0&&echoAttack!=attackAt){echoAttack=attackAt;SpawnQi();}
   var area=new Rect(player.X+attackFacing*48-48,player.CenterY-50,96,90);foreach(var t in Targets())if(!meleeHits.Contains(t)&&area.Overlaps(t.Bounds)){meleeHits.Add(t);Strike(t,attackFacing);}
