  public void Strike(Actor t,int dir,bool ranged=false,float amount=-1){if(t==null||t.hp<=0)return;t.hitAt=clock;bool isBoss=t==boss;float dmg=amount>=0?amount:ranged?(isBoss?9:3):(isBoss&&(t.state=="recover"||t.state=="wallStun")?4:2);bool critical=run!=null&&run.CriticalChance>0&&random.NextDouble()<run.CriticalChance;float finalDamage=dmg*DamageScale*(critical?1.65f:1);LastStrikeDamage=finalDamage;t.hp=Mathf.Max(0,t.hp-finalDamage);if(critical){ui.ShowFormationDamage(finalDamage,t.X,t.CenterY,true);fx.Sprite("swordImpact","0",t.X,t.CenterY,95,95,clock,.2f,new Color(1,.84f,.52f,.7f),additive:true);}audio.Play("hit");if(!ranged)fx.Animated("pixelHit",6,t.X,Mathf.Clamp(player.CenterY,t.Bounds.yMin+10,t.Bounds.yMax-10),72,89,clock,.24f,Color.white,follow:t);if(amount<0)Shake(1.8f,.07f);
   if(!isBoss){t.VX=dir*150;t.windup=0;t.chargeUntil=clock-.001f;if(t.hp<=0){if(run!=null){run.kills++;if(run.kills%3==0)hp=Mathf.Min(MaxHP,hp+run.Level("blood")*.5f);}fx.Burst(t.X,t.CenterY,18,new Color(.55f,.78f,.7f),clock);t.Disable();}}
   else if(t.hp<=0){t.Disable();if(t.kind=="master")masterDefeated=true;else stoneDefeated=true;Shake(7,.3f);fx.Burst(t.X,t.CenterY,40,new Color(1,.8f,.5f),clock);audio.Play("heavy");audio.Boss(false);RefreshHerbs();Notice(endless?(PendingEnemies>0||LivingEnemies()>0?"首领已破 · 清除魔门伏兵":"破阵 · 双重机缘"):"封印已破 · 向前继续",3);}
  }
  public bool Damage(bool fall,float from,bool pierceDash=false,float custom=-1){if(phase!=GamePhase.Play&&phase!=GamePhase.WaveClear)return false;if(!fall&&(clock<invincibleUntil||(!pierceDash&&clock<dashUntil)))return false;
   int shield=run?.Level("shield")??0;if(!fall&&shield>0&&clock>=run.shieldReady){run.shieldReady=clock+12-(shield-1)*2;invincibleUntil=clock+.35f;fx.Ring(player.X,player.CenterY,112,112,new Color(1,.85f,.45f),clock,.4f,4);audio.Play("heavy");return false;}
   float incoming=custom>=0?custom:endless?Rules.Wave(run.wave).damage:1;if(!fall)incoming*=run?.IncomingScale??1;hp-=incoming;hp=Mathf.Max(0,hp);audio.Play("heavy");Shake(4,.16f);invincibleUntil=clock+settings.invincibleDuration;hurtUntil=clock+.22f;dashUntil=0;player.body.gravityScale=1;player.VX=(player.X>=from?1:-1)*190;player.VY=-170;fx.Burst(player.X,player.CenterY,12,new Color(1,.48f,.4f),clock);
   if(hp<=0){if(run!=null&&run.Level("revive")>0&&!run.revived){run.revived=true;hp=MaxHP*.5f;player.Place(170,620);invincibleUntil=clock+3.5f;fx.Ring(player.X,player.CenterY,180,180,new Color(1,.9f,.5f),clock,.7f,4);Notice("涅槃归真",2);return true;}deaths++;ClearCombat();player.VX=player.VY=0;if(endless){phase=GamePhase.EndlessOver;ui.ShowEndlessOver();}else{phase=GamePhase.Dead;deadUntil=clock+1.1f;Notice("气血已尽 · 返回山门",1.1f);}}
   else if(fall){player.Place(checkpointRoom==room?checkpointX:170,checkpointRoom==room?checkpointFeet:620);invincibleUntil=clock+1.8f;}return true;
  }
  void ContactDamage(){foreach(var e in enemies){if(e.hp<=0||clock<e.spawnGraceUntil)continue;Rect hit=e.Bounds;if(!e.IsFlying)hit=new Rect(e.X-e.width/2,e.Feet-76,e.width,76);if(player.Bounds.Overlaps(hit))Damage(false,e.X,custom:e.attackPower);}if(boss==null||!boss.active||boss.hp<=0)return;if(boss.kind=="master"){if(player.Bounds.Overlaps(boss.Bounds))Damage(false,boss.X);return;}var p=player.Bounds;float dx=boss.X-Mathf.Clamp(boss.X,p.xMin,p.xMax),dy=boss.Feet-Mathf.Clamp(boss.Feet,p.yMin,p.yMax);if(p.yMin<boss.Feet&&dx*dx/(72*72)+dy*dy/(172*172)<1)Damage(false,boss.X);}
