  static float Turn(float current,float target,float step)=>current+Mathf.Clamp(Mathf.DeltaAngle(current*Mathf.Rad2Deg,target*Mathf.Rad2Deg)*Mathf.Deg2Rad,-step,step);
  void UpdateProjectiles(float dt){for(int i=projectiles.Count-1;i>=0;i--){var p=projectiles[i];float age=clock-p.born,old=p.x,oldY=p.y;bool gone=false;if(p.tracking&&age<1.5f)p.angle=Turn(p.angle,Mathf.Atan2(player.CenterY-14-p.y,player.X-p.x),2*dt);
    if(!p.hostile&&!p.qi&&!p.rain){if(!p.returning&&(age>=.65f||p.x<0||p.x>Width||Blocked(p.x,p.y)))p.returning=true;if(p.returning){float dx=player.X+facing*12-p.x,dy=player.CenterY-13-p.y;if(dx*dx+dy*dy<1600||age>2.4f)gone=true;else{p.angle=Mathf.Atan2(dy,dx);p.speed=850;}}}
    p.x+=Mathf.Cos(p.angle)*p.speed*dt;p.y+=Mathf.Sin(p.angle)*p.speed*dt;
    if(p.rain){foreach(var t in Targets())if(SegmentContact(new Vector2(old,oldY),new Vector2(p.x,p.y),t.Bounds,9,out var contact)){Strike(t,p.x>=player.X?1:-1,true,p.damage);SwordImpact(contact.x,contact.y,p.angle,false);gone=true;break;}gone|=age>1.6f||p.y>690;p.view.Image("blade","0",p.x,p.y,8,76,p.angle+Mathf.PI/2);p.view.Color(new Color(.83f,1,.9f));fx.Line(new[]{new Vector2(p.x-Mathf.Cos(p.angle)*45,p.y-Mathf.Sin(p.angle)*45),new Vector2(p.x,p.y)},2,new Color(.7f,.95f,.78f,.5f),clock,.06f);}
    else if(p.qi){foreach(var t in Targets())if(!p.hits.Contains(t)&&SegmentHits(new Vector2(old,oldY),new Vector2(p.x,p.y),t.Bounds,32)){p.hits.Add(t);Strike(t,Mathf.Cos(p.angle)>0?1:-1,true,p.damage);SwordImpact(t.X,t.CenterY,p.angle,false);}gone|=age*p.speed>p.range||p.x<0||p.x>Width;bool left=Mathf.Cos(p.angle)<0;p.view.Image("qiSlash",(3+Mathf.FloorToInt(age/.08f)%3).ToString(),p.x,p.y,125,120,left?p.angle-Mathf.PI:p.angle);p.view.renderer.flipX=left;p.view.Color(new Color(.65f,1,.84f,Mathf.Clamp01((p.range-age*p.speed)/100)));}
    else if(p.hostile){gone|=age>3.6f||p.x<0||p.x>Width||Blocked(p.x,p.y);if(!gone&&SegmentHits(new Vector2(old,oldY),new Vector2(p.x,p.y),player.Bounds,8)){Damage(false,p.x,custom:p.damage);gone=true;}if(p.tracking){p.view.Image("wuxiaAtlas","talisman",p.x,p.y,25,45,p.angle+Mathf.PI/2);p.view.Color(new Color(.9f,.65f,1));}else p.view.Image("enemyBlade","0",p.x,p.y,17,59,p.angle+Mathf.PI/2);fx.Line(new[]{new Vector2(p.x-Mathf.Cos(p.angle)*38,p.y-Mathf.Sin(p.angle)*38),new Vector2(p.x,p.y)},2,p.tracking?new Color(.75f,.4f,1,.55f):new Color(1,.4f,.2f,.5f),clock,.06f);}
    else {if(!p.returning)foreach(var t in Targets())if(SegmentContact(new Vector2(old,oldY),new Vector2(p.x,p.y),t.Bounds,10,out var contact)){Strike(t,Mathf.Cos(p.angle)>0?1:-1,true);p.returning=true;SwordImpact(contact.x,contact.y,p.angle,true);break;}p.view.Image("blade","0",p.x,p.y,9,86,p.angle+Mathf.PI/2);fx.Line(new[]{new Vector2(p.x-Mathf.Cos(p.angle)*42,p.y-Mathf.Sin(p.angle)*42),new Vector2(p.x,p.y)},2,new Color(.6f,.95f,.9f,.48f),clock,.06f);}
    if(gone){p.view.Destroy();projectiles.RemoveAt(i);}
   }
   for(int i=waves.Count-1;i>=0;i--){var w=waves[i];float oldX=w.x;w.x+=w.dir*(w.strong?360:245)*dt;float h=w.strong?36:25;var hurt=new Rect(Mathf.Min(oldX,w.x)-(w.strong?25:15),601-h/2,Mathf.Abs(w.x-oldX)+(w.strong?50:30),h);if(hurt.Overlaps(player.Bounds))Damage(false,w.x);float visualH=w.strong?70:49+Mathf.Sin((clock-w.born)*20)*3;w.view.Image("wuxiaAtlas","spikes",w.x,624-visualH/2,w.strong?130:87,visualH);w.view.renderer.flipX=w.dir<0;w.view.Color(w.strong?new Color(.73f,.63f,.91f):Color.white);if(Mathf.FloorToInt(clock*60)%4==0)fx.Sprite("wuxiaAtlas","stoneTop",w.x-w.dir*22,617,5,4,clock,.3f,new Color(.76f,.68f,.58f),-w.dir*32,-48,true);if(w.x<0||w.x>Width||clock-w.born>4.8f){w.view.Destroy();waves.RemoveAt(i);}}
