  void DestroyFormationSword(FlyingSword s){s.view.Destroy();if(s.trail)NativeObject.Remove(s.trail.gameObject);}
  void CastFormation(){formationAt=clock;formationReady=clock+settings.formationCooldown*Cooldown;formationHits=0;FormationDamage=0;ui.ClearFormationDamage();foreach(var s in formation)DestroyFormationSword(s);formation.Clear();
   for(int i=0;i<12;i++){float a=i*Mathf.PI/6-Mathf.PI/2;var view=new SpriteView(art,effectRoot,"万剑 · "+i,30);view.Additive();formation.Add(new FlyingSword{view=view,x=player.X+Mathf.Cos(a)*48,y=player.CenterY-70+Mathf.Sin(a)*48*.78f,angle=a,orbitAngle=a,born=clock,launch=clock+.42f+i*.035f});}
   if(sealOuter==null){sealOuter=new SpriteView(art,effectRoot,"归宗法阵 · 外环",16);sealInner=new SpriteView(art,effectRoot,"归宗法阵 · 内环",17);sealGlow=new SpriteView(art,effectRoot,"归宗法阵 · 柔光",15);sealOuter.Additive();sealInner.Additive();sealGlow.Additive(true,true);}audio.Play("heavy");Shake(3,.13f);
