  void SwordTrail(FlyingSword s){
   if(!s.trail){var go=new GameObject("万剑 · 渐变剑轨");go.transform.SetParent(effectRoot,false);s.trail=go.AddComponent<LineRenderer>();s.trail.sharedMaterial=art.AdditiveMaterial;s.trail.useWorldSpace=true;s.trail.sortingOrder=29;s.trail.numCapVertices=3;s.trail.numCornerVertices=3;s.trail.widthCurve=AnimationCurve.Linear(0,.024f,1,.052f);var gradient=new Gradient();gradient.SetKeys(new[]{new GradientColorKey(new Color(.5f,.84f,.77f),0),new GradientColorKey(new Color(.97f,.89f,.63f),1)},new[]{new GradientAlphaKey(0,0),new GradientAlphaKey(.65f,1)});s.trail.colorGradient=gradient;}
   if(s.historyCount==9){for(int i=0;i<8;i++)s.history[i]=s.history[i+1];}else s.historyCount++;
   s.history[s.historyCount-1]=PixelWorld.Position(s.x,s.y);s.trail.positionCount=s.historyCount;for(int i=0;i<s.historyCount;i++)s.trail.SetPosition(i,s.history[i]);
