  Actor Nearest(float x,float y,float range,bool prioritizeBoss=false){if(prioritizeBoss&&boss!=null&&boss.active&&boss.hp>0&&Vector2.Distance(new Vector2(x,y),new Vector2(boss.X,boss.CenterY))<=range)return boss;Actor nearest=null;float distance=range*range;foreach(var t in Targets()){float d=(t.X-x)*(t.X-x)+(t.CenterY-y)*(t.CenterY-y);if(d<distance){distance=d;nearest=t;}}return nearest;}
  void UpdateFormation(float dt){float age=clock-formationAt;if(sealOuter!=null){bool show=age>=0&&age<1.12f;sealOuter.Visible(show);sealInner.Visible(show);sealGlow.Visible(show);if(show){float rise=Mathf.Clamp01(age/.35f),release=age<.42f?0:Mathf.Max(0,1-(age-.42f)/.22f),fade=age<.68f?1:1-(age-.68f)/.44f,scale=.45f+.55f*(1-Mathf.Pow(1-rise,3))+release*.12f,alpha=Mathf.Min(1,rise*1.4f)*fade*.88f,x=player.X-facing*12,y=player.CenterY-88;
    sealOuter.Image("formationOuter","0",x,y,246*scale,246*scale,age*.38f);sealInner.Image("formationInner","0",x,y,224*scale,224*scale,-age*.55f);sealGlow.Image("whitePixel","0",x,y,(150+release*90)*scale,(150+release*90)*scale);sealOuter.Color(new Color(1,1,1,alpha));sealInner.Color(new Color(1,1,1,alpha));sealGlow.Color(new Color(.67f,.90f,.82f,alpha*(.18f+release*.48f)));}}
   for(int i=formation.Count-1;i>=0;i--){var s=formation[i];bool gone=clock-s.born>3.3f;
    if(clock>=s.launch){
     if(!s.launched){s.launched=true;s.target=Nearest(s.x,s.y,2000,true);s.angle=s.target!=null?Mathf.Atan2(s.target.CenterY-s.y,s.target.X-s.x):facing>0?0:Mathf.PI;if(i==formation.Count-1)Shake(4,.17f);}
     if(s.target!=null&&(s.target.hp<=0||!s.target.body.simulated))s.target=null;
     if(s.target==null)s.target=Nearest(s.x,s.y,2000,true);
     var before=new Vector2(s.x,s.y);float speed=Mathf.Lerp(560,1050,Mathf.Clamp01((clock-s.launch)/.5f));
     if(s.target!=null){var aim=new Vector2(s.target.X,s.target.CenterY);float wanted=Mathf.Atan2(aim.y-s.y,aim.x-s.x);s.angle=Turn(s.angle,wanted,9*dt);if(Vector2.Distance(before,aim)<110){var next=Vector2.MoveTowards(before,aim,speed*dt);s.x=next.x;s.y=next.y;s.angle=wanted;}else{s.x+=Mathf.Cos(s.angle)*speed*dt;s.y+=Mathf.Sin(s.angle)*speed*dt;}}
     else {s.x+=Mathf.Cos(s.angle)*speed*dt;s.y+=Mathf.Sin(s.angle)*speed*dt;}
     SwordTrail(s);
     foreach(var t in Targets())if(SegmentContact(before,new Vector2(s.x,s.y),t.Bounds,12,out var contact)){Strike(t,Mathf.Cos(s.angle)>0?1:-1,true,2);formationHits++;FormationDamage+=LastStrikeDamage;bool heavy=formationHits==1||formationHits==12||t.hp<=0;SwordImpact(contact.x,contact.y,s.angle,heavy);ui.ShowFormationDamage(FormationDamage,contact.x,contact.y,heavy);gone=true;break;}
    }else {float a=s.orbitAngle+Mathf.Sin(age*3)*.12f,r=48+Mathf.Min(1,age/.32f)*44;s.angle=a;s.x=player.X+Mathf.Cos(a)*r;s.y=player.CenterY-70+Mathf.Sin(a)*r*.78f;}
    s.view.Image("blade","0",s.x,s.y,10,76,s.angle+Mathf.PI/2);s.view.Color(new Color(.85f,1,.94f,Mathf.Min(1,age/.16f)));if(gone){DestroyFormationSword(s);formation.RemoveAt(i);}
   }
  }
