   fx.Sprite("swordPierce","0",x,y,heavy?260:190,heavy?68:42,clock,.22f,new Color(1,.94f,.79f,.65f),Mathf.Cos(angle)*227,Mathf.Sin(angle)*227,angle:angle,additive:true);
