  // Place impacts at the segment entry point, rather than an already overshot frame endpoint.
  public static bool SegmentHits(Vector2 from,Vector2 to,Rect bounds,float padding)=>SegmentContact(from,to,bounds,padding,out _);
  public static bool SegmentContact(Vector2 from,Vector2 to,Rect bounds,float padding,out Vector2 contact){var visible=bounds;contact=to;bounds.xMin-=padding;bounds.yMin-=padding;bounds.xMax+=padding;bounds.yMax+=padding;float lo=0,hi=1;var delta=to-from;for(int axis=0;axis<2;axis++){float origin=axis==0?from.x:from.y,d=axis==0?delta.x:delta.y,min=axis==0?bounds.xMin:bounds.yMin,max=axis==0?bounds.xMax:bounds.yMax;if(Mathf.Abs(d)<.00001f){if(origin<min||origin>max)return false;}else{float a=(min-origin)/d,b=(max-origin)/d;if(a>b){float tmp=a;a=b;b=tmp;}lo=Mathf.Max(lo,a);hi=Mathf.Min(hi,b);if(lo>hi)return false;}}contact=from+delta*lo;contact.x=Mathf.Clamp(contact.x,visible.xMin,visible.xMax);contact.y=Mathf.Clamp(contact.y,visible.yMin,visible.yMax);return true;}
  void UpdateRogue(float dt){if(run==null)return;UpdateNewRogueSkills();int n=run.Level("orbit"),count=n>0?n+1:0;while(orbit.Count<count)orbit.Add(new SpriteView(art,effectRoot,"护体飞剑",25));while(orbit.Count>count){orbit[orbit.Count-1].Destroy();orbit.RemoveAt(orbit.Count-1);}for(int i=0;i<orbit.Count;i++){float a=clock*2.5f+i*Mathf.PI*2/count,x=player.X+Mathf.Cos(a)*90,y=player.CenterY+Mathf.Sin(a)*62;orbit[i].Image("blade","0",x,y,8,58,a+Mathf.PI/2);if(clock>=orbitHitAt)foreach(var t in Targets())if(Mathf.Abs(t.X-x)<35&&Mathf.Abs(t.CenterY-y)<(t==boss?90:45)){Strike(t,t.X>player.X?1:-1,true,1+n);orbitHitAt=clock+.55f;break;}}
   n=run.Level("thunder");if(n>0&&clock>=run.nextThunder){run.nextThunder=clock+5*Cooldown;var targets=Targets();targets.Sort((a,b)=>Mathf.Abs(a.X-player.X).CompareTo(Mathf.Abs(b.X-player.X)));for(int i=0;i<Mathf.Min(Mathf.CeilToInt(n/2f),targets.Count);i++){var t=targets[i];if(Mathf.Abs(t.X-player.X)>730)continue;fx.Line(new[]{new Vector2(t.X-22,100),new Vector2(t.X+14,270),new Vector2(t.X-12,390),new Vector2(t.X,t.CenterY)},5,new Color(.88f,.87f,1),clock,.3f);Strike(t,1,true,5+3*n);Shake(3,.15f);}}
   n=run.Level("frost");if(n>0&&clock>=run.nextFrost){run.nextFrost=clock+6*Cooldown;float radius=150+n*25;fx.Animated("pixelMist",24,player.X,player.CenterY,160,130,clock,.42f,Color.white);foreach(var t in Targets())if(Mathf.Abs(t.X-player.X)<radius){t.frozenUntil=clock+2.2f;Strike(t,1,true,2+2*n);if(t.hp>0)fx.Animated("pixelFrost",36,t.X,t.CenterY,110,120,clock,2.2f,Color.white,follow:t,order:18);}}
  }
