  public void RenderActors(){if(player==null)return;float age=clock-attackAt,castAge=clock-castAt;string sheet="hero";int frame=clock<hurtUntil?10:clock<dashUntil?9:castAge<.57f?(castAge<.26f?6:7):!player.Grounded?(player.VY<0?4:5):0;float scale=settings.heroHeight/art.Frame("hero","0").h;int dir=facing;
